// ============================================================================
// tests/unit/ext_better_water_test.cpp -- ext.better_water's shore program and its row
// ============================================================================
// src/render/common/better_water/shore_overlay_{river,lake}_ps.h are generated by tools/water_shaders.py (fxc) and
// checked in. These cases catch a stale or hand-edited header: each blob is a well-formed DXBC
// container whose checksum matches, it is a ps_4_0 pixel program, and its input signature is the
// prefix of the water vertex program's outputs the overlay relies on (handins/BETTERWATER.md): the
// registers line up with the vertex program's, so the second pass reads the water's own
// interpolants. Plus the registry row (class A, default on like every class A row).
// ============================================================================
#include "unit.h"

#include "better_trees/dxbc.h"
#include "better_water/shore_overlay_lake_ps.h"
#include "better_water/shore_overlay_river_ps.h"
#include "ext/registry.h"

#include <cstring>
#include <string>

namespace {

uint32_t U32(const std::vector<uint8_t>& d, size_t at) {
    uint32_t v = 0;
    std::memcpy(&v, d.data() + at, 4);
    return v;
}

struct Blob {
    const uint8_t* data;
    size_t size;
};
const Blob kBlobs[2] = {
    { g_bw_PSShoreRiver, sizeof(g_bw_PSShoreRiver) },
    { g_bw_PSShoreLake, sizeof(g_bw_PSShoreLake) },
};

}  // namespace

UNIT_TEST(ext_better_water_shore_blob_is_a_valid_container) {
    for (const Blob& b : kBlobs) {
        Dxbc::Container c;
        std::string err;
        CHECK(Dxbc::Parse(b.data, b.size, &c, &err));
        uint32_t sum[4] = {0, 0, 0, 0};
        Dxbc::Checksum(b.data, b.size, sum);
        CHECK(std::memcmp(sum, c.checksum, sizeof(sum)) == 0);
    }
}

UNIT_TEST(ext_better_water_shore_blob_is_ps_4_0) {
    for (const Blob& b : kBlobs) {
        Dxbc::Container c;
        std::string err;
        CHECK(Dxbc::Parse(b.data, b.size, &c, &err));
        const Dxbc::Chunk* shdr = c.Find(Dxbc::FourCC('S', 'H', 'D', 'R'));
        CHECK(shdr != nullptr);
        if (shdr == nullptr) continue;
        const uint32_t version = U32(shdr->data, 0);
        CHECK((version >> 16) == 0);          // program type 0 = pixel
        CHECK(((version >> 4) & 0xF) == 4);   // major 4
        CHECK((version & 0xF) == 0);          // minor 0
    }
}

UNIT_TEST(ext_better_water_shore_inputs_match_the_water_interpolants) {
    struct Want { const char* name; uint32_t index; uint32_t reg; };
    const Want want[5] = {
        { "SV_Position", 0, 0 },   // the clip position
        { "TEXCOORD", 0, 1 },      // the two scrolling uv sets
        { "TEXCOORD", 1, 2 },      // the view direction
        { "TEXCOORD", 2, 3 },      // the projective screen coordinate
        { "TEXCOORD", 3, 4 },      // lighting / fog / the mesh alpha
    };
    for (const Blob& b : kBlobs) {
        Dxbc::Container c;
        std::string err;
        CHECK(Dxbc::Parse(b.data, b.size, &c, &err));
        const Dxbc::Chunk* isgn = c.Find(Dxbc::FourCC('I', 'S', 'G', 'N'));
        CHECK(isgn != nullptr);
        if (isgn == nullptr) continue;
        const std::vector<uint8_t>& d = isgn->data;
        // ISGN: u32 count, u32 8, then count x { name offset, semantic index, system value, component
        // type, register, mask bytes } of 24 bytes; names are offsets into the chunk data.
        const uint32_t count = U32(d, 0);
        CHECK(count == 5);
        if (count != 5) continue;
        for (uint32_t i = 0; i < count; ++i) {
            const size_t e = 8 + i * 24;
            const char* name = reinterpret_cast<const char*>(d.data() + U32(d, e));
            CHECK(std::strcmp(name, want[i].name) == 0);
            CHECK(U32(d, e + 4) == want[i].index);
            CHECK(U32(d, e + 16) == want[i].reg);
        }
    }
}

UNIT_TEST(ext_better_water_row_is_class_a_default_on) {
    const Ext::Entry* row = Ext::FindEntry("better_water");
    CHECK(row != nullptr);
    if (row == nullptr) return;
    CHECK(row->cls == Ext::Class::A);
    CHECK(row->defaultOn);
}
